descriptor.templateCss:
.trend-card-container.pcs {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 10px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #38BDF8;
  padding: 12px 18px 10px 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.trend-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.trend-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.trend-icon { font-size: 16px; }
.trend-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
  color: #38BDF8;
  border: 1.5px solid #38BDF8;
  background: rgba(56, 189, 248, 0.12);
}
.trend-kpi-bar {
  display: flex;
  justify-content: space-around;
  align-items: center;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.12);
  border-radius: 8px;
  padding: 5px 12px 6px 12px;
  margin: 6px 0 4px 0;
}
.kpi-col {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.kpi-lbl { font-size: 10px; font-weight: 700; color: #64748b; letter-spacing: 0.5px; }
.kpi-val-group { display: flex; align-items: baseline; gap: 4px; }
.kpi-num { font-size: 19px; font-weight: 800; line-height: 1.1; }
.kpi-unit { font-size: 12px; font-weight: 600; color: #94a3b8; }
.kpi-sub { font-size: 10px; font-weight: 600; color: #94a3b8; margin-top: 1px; letter-spacing: 0.3px; }
.kpi-divider { width: 1px; height: 32px; background: rgba(148, 163, 184, 0.15); }
.chart-wrapper {
  width: 100%;
  flex: 1;
  min-height: 130px;
  position: relative;
}
.trend-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 4px;
  margin-top: 2px;
}

descriptor.controllerScript:
self.onInit = function() {
  self.initChart();
  self.setupHoverSync();
  self.onDataUpdated();
};


self.ensureEcharts = function(cb) {
  if (window.echarts) {
    cb();
    return;
  }
  var existing = document.querySelector('script[src*="echarts"]');
  if (!existing) {
    var s = document.createElement('script');
    s.src = '/echarts.min.js';
    s.onload = cb;
    document.head.appendChild(s);
  } else {
    existing.addEventListener('load', cb);
    var attempts = 0;
    var intv = setInterval(function() {
      attempts++;
      if (window.echarts || attempts > 50) {
        clearInterval(intv);
        if (window.echarts) cb();
      }
    }, 100);
  }
};

self.initChart = function() {
  var container = self.ctx.$container ? (self.ctx.$container[0] || self.ctx.$container) : null;
  if (!container) return;
  var el = container.querySelector('#echarts-pcs');
  if (!el) return;

  self.ensureEcharts(function() {
    if (!self.myChart && window.echarts && el.clientWidth > 0 && el.clientHeight > 0) {
      self.myChart = window.echarts.init(el);
      if (self.onResize) self.onResize();
      if (self.onDataUpdated) self.onDataUpdated();
    } else if (!self.myChart && window.echarts) {
      setTimeout(function() {
        if (!self.myChart && el.clientWidth > 0 && el.clientHeight > 0) {
          self.myChart = window.echarts.init(el);
          if (self.onResize) self.onResize();
          if (self.onDataUpdated) self.onDataUpdated();
        }
      }, 200);
    }
  });
};

self.setupHoverSync = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container) return;
  var wrapper = container.querySelector('.chart-wrapper');
  if (wrapper && !self.hasHoverBound) {
    self.hasHoverBound = true;
    wrapper.addEventListener('mouseleave', function() {
      self.restoreDefaultCards();
    });
  }
};

self.onResize = function() {
  if (self.myChart) {
    self.myChart.resize();
  } else {
    self.initChart();
  }
};

self.restoreDefaultCards = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container || !self.cardMetrics) return;

  var m = self.cardMetrics;
  var el1 = container.querySelector('#pcs1-live-val');
  var el1s = container.querySelector('#pcs1-sub-val');
  var el2 = container.querySelector('#pcs2-live-val');
  var el2s = container.querySelector('#pcs2-sub-val');
  var el3 = container.querySelector('#pcs3-live-val');
  var el3s = container.querySelector('#pcs3-sub-val');

  var fmt = function(v) { return (v != null && !isNaN(v) ? Number(v) : 0).toFixed(1); };

  if (el1 && m.pcs1) el1.textContent = fmt(m.pcs1.primary);
  if (el1s && m.pcs1) el1s.textContent = m.pcs1.sub || 'En Vivo';

  if (el2 && m.pcs2) el2.textContent = fmt(m.pcs2.primary);
  if (el2s && m.pcs2) el2s.textContent = m.pcs2.sub || 'En Vivo';

  if (el3 && m.pcs3) el3.textContent = fmt(m.pcs3.primary);
  if (el3s && m.pcs3) el3s.textContent = m.pcs3.sub || 'En Vivo';
};

self.onHoverPoint = function(params) {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container || !params || params.length === 0) return;

  var d = new Date(params[0].value[0]);
  var months = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
  var timeStr = months[d.getMonth()] + ' ' + d.getDate() + ' ' + d.toTimeString().split(' ')[0].substring(0, 5);

  var v1 = null, v2 = null, v3 = null;
  for (var i = 0; i < params.length; i++) {
    var p = params[i];
    var sName = p.seriesName || '';
    if (sName.indexOf('PCS-01') !== -1) v1 = parseFloat(p.value[1]);
    else if (sName.indexOf('PCS-02') !== -1) v2 = parseFloat(p.value[1]);
    else if (sName.indexOf('PCS-03') !== -1) v3 = parseFloat(p.value[1]);
  }

  var el1 = container.querySelector('#pcs1-live-val');
  var el1s = container.querySelector('#pcs1-sub-val');
  var el2 = container.querySelector('#pcs2-live-val');
  var el2s = container.querySelector('#pcs2-sub-val');
  var el3 = container.querySelector('#pcs3-live-val');
  var el3s = container.querySelector('#pcs3-sub-val');

  if (v1 !== null && el1) {
    el1.textContent = v1.toFixed(1);
    if (el1s) el1s.textContent = timeStr;
  }
  if (v2 !== null && el2) {
    el2.textContent = v2.toFixed(1);
    if (el2s) el2s.textContent = timeStr;
  }
  if (v3 !== null && el3) {
    el3.textContent = v3.toFixed(1);
    if (el3s) el3s.textContent = timeStr;
  }
};

self.smoothSeries = function(pts, targetWindow) {
  if (!pts || pts.length <= 5) return pts;
  var w = targetWindow || 15;
  if (pts.length < 150) w = 3;
  else if (pts.length < 600) w = 7;
  else if (pts.length < 1800) w = 15;
  else w = 21;

  var half = Math.floor(w / 2);
  var res = [];
  for (var i = 0; i < pts.length; i++) {
    var sum = 0, count = 0;
    var start = Math.max(0, i - half);
    var end = Math.min(pts.length - 1, i + half);
    for (var j = start; j <= end; j++) {
      sum += pts[j][1];
      count++;
    }
    res.push([pts[i][0], Math.round((sum / count) * 10) / 10]);
  }
  return res;
};

self.onDataUpdated = function() {
  var data = self.ctx.data || [];
  var raw1 = [], raw2 = [], raw3 = [];
  var v1 = [], v2 = [], v3 = [];

  for (var i = 0; i < data.length; i++) {
    var item = data[i];
    var pts = item.data || [];
    var k = (item.dataKey.name || item.dataKey.label || '').toLowerCase();

    if (pts.length > 0) {
      if (k.indexOf('pcs1') !== -1 || k.indexOf('pcs-01') !== -1 || k.indexOf('12136') !== -1) {
        raw1 = pts.map(function(p) { return [p[0], parseFloat(p[1]) || 0]; });
        v1 = pts.map(function(p) { return parseFloat(p[1]) || 0; });
      } else if (k.indexOf('pcs2') !== -1 || k.indexOf('pcs-02') !== -1 || k.indexOf('12135') !== -1) {
        raw2 = pts.map(function(p) { return [p[0], parseFloat(p[1]) || 0]; });
        v2 = pts.map(function(p) { return parseFloat(p[1]) || 0; });
      } else if (k.indexOf('pcs3') !== -1 || k.indexOf('pcs-03') !== -1 || k.indexOf('12134') !== -1) {
        raw3 = pts.map(function(p) { return [p[0], parseFloat(p[1]) || 0]; });
        v3 = pts.map(function(p) { return parseFloat(p[1]) || 0; });
      }
    }
  }

  raw1.sort(function(a, b) { return a[0] - b[0]; });
  raw2.sort(function(a, b) { return a[0] - b[0]; });
  raw3.sort(function(a, b) { return a[0] - b[0]; });

  var calcStats = function(arr, fallbackLast) {
    var fb = (fallbackLast != null && !isNaN(fallbackLast)) ? Number(fallbackLast) : 0;
    if (!arr || arr.length === 0) {
      return { avg: fb, maxAbs: Math.abs(fb), maxSigned: fb, last: fb };
    }
    var sum = 0, maxAbs = 0, maxSigned = arr[0];
    for (var j = 0; j < arr.length; j++) {
      var val = arr[j];
      sum += val;
      if (Math.abs(val) > maxAbs) {
        maxAbs = Math.abs(val);
        maxSigned = val;
      }
    }
    return {
      avg: sum / arr.length,
      maxAbs: maxAbs,
      maxSigned: maxSigned != null ? maxSigned : fb,
      last: arr[arr.length - 1] != null ? arr[arr.length - 1] : fb
    };
  };

  var s1 = calcStats(v1, -179.3);
  var s2 = calcStats(v2, -183.0);
  var s3 = calcStats(v3, -184.0);

  var isHistorical = false;
  if (self.ctx.timeWindow) {
    if (self.ctx.timeWindow.isRealtime === false) isHistorical = true;
    else if (self.ctx.timeWindow.realtime && self.ctx.timeWindow.realtime.timewindowMs > 3600000 * 12) isHistorical = true;
  }

  var fmt = function(v) { return (v != null && !isNaN(v) ? Number(v) : 0).toFixed(1); };

  if (isHistorical) {
    self.cardMetrics = {
      pcs1: { primary: s1.avg, sub: 'Pico: ' + fmt(s1.maxSigned) + ' kW' },
      pcs2: { primary: s2.avg, sub: 'Pico: ' + fmt(s2.maxSigned) + ' kW' },
      pcs3: { primary: s3.avg, sub: 'Pico: ' + fmt(s3.maxSigned) + ' kW' }
    };
  } else {
    self.cardMetrics = {
      pcs1: { primary: s1.last, sub: 'Pico: ' + fmt(s1.maxSigned) + ' kW' },
      pcs2: { primary: s2.last, sub: 'Pico: ' + fmt(s2.maxSigned) + ' kW' },
      pcs3: { primary: s3.last, sub: 'Pico: ' + fmt(s3.maxSigned) + ' kW' }
    };
  }

  self.restoreDefaultCards();

  // Balance status in footer
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elStatus = container.querySelector('#pcs-balance-status');
    if (elStatus) {
      var lastVals = [s1.last, s2.last, s3.last];
      var minP = Math.min.apply(null, lastVals);
      var maxP = Math.max.apply(null, lastVals);
      var deltaP = Math.abs(maxP - minP);
      if (deltaP <= 15) {
        elStatus.innerHTML = '<span style="color:#64B856;">Equilibrado (ΔP: ' + deltaP.toFixed(1) + ' kW)</span>';
      } else {
        elStatus.innerHTML = '<span style="color:#F59E0B;">Dispersión Ligera (ΔP: ' + deltaP.toFixed(1) + ' kW)</span>';
      }
    }
  }

  if (!self.myChart) {
    self.initChart();
  }
  if (!self.myChart) return;

  var clean1 = self.smoothSeries(raw1, 15);
  var clean2 = self.smoothSeries(raw2, 15);
  var clean3 = self.smoothSeries(raw3, 15);

  var monthsShort = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];

  var option = {
    backgroundColor: 'transparent',
    tooltip: {
      trigger: 'axis',
      confine: true,
      alwaysShowContent: false,
      hideDelay: 500,
      extraCssText: 'z-index: 999999; box-shadow: 0 4px 20px rgba(0,0,0,0.7); pointer-events: none;',
      backgroundColor: 'rgba(15, 23, 42, 0.95)',
      borderColor: 'rgba(56, 189, 248, 0.4)',
      borderWidth: 1,
      padding: [8, 12],
      textStyle: { color: '#f8fafc', fontSize: 11 },
      axisPointer: {
        type: 'line',
        snap: true,
        lineStyle: { color: 'rgba(255, 255, 255, 0.4)', width: 1.5, type: 'dashed' }
      },
      formatter: function(params) {
        if (!params || params.length === 0) return '';
        self.onHoverPoint(params);
        var d = new Date(params[0].value[0]);
        var timeStr = monthsShort[d.getMonth()] + ' ' + d.getDate() + ', ' + d.toTimeString().split(' ')[0];
        var out = '<div style="font-weight:700; margin-bottom:5px; color:#38BDF8; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:3px;">⚡ ' + timeStr + '</div>';
        params.forEach(function(p) {
          out += '<div style="display:flex; justify-content:space-between; gap:16px; margin: 3px 0;">' +
                 '<span>' + p.marker + ' ' + p.seriesName + ':</span>' +
                 '<strong style="color:#ffffff;">' + p.value[1] + ' kW</strong>' +
                 '</div>';
        });
        return out;
      }
    },
    grid: {
      left: 50,
      right: 25,
      top: 15,
      bottom: 28,
      containLabel: false
    },
    dataZoom: [
      {
        type: 'slider',
        show: true,
        bottom: 2,
        height: 18,
        borderColor: 'rgba(56, 189, 248, 0.3)',
        backgroundColor: 'rgba(14, 25, 16, 0.7)',
        fillerColor: 'rgba(56, 189, 248, 0.22)',
        handleStyle: { color: '#38BDF8', borderColor: '#0284C7' },
        moveHandleStyle: { color: 'rgba(56, 189, 248, 0.4)' },
        showDetail: true,
        showDataShadow: true,
        dataBackground: {
          lineStyle: { color: '#38BDF8', width: 1 },
          areaStyle: { color: 'rgba(56, 189, 248, 0.25)' }
        },
        selectedDataBackground: {
          lineStyle: { color: '#10B981', width: 1 },
          areaStyle: { color: 'rgba(16, 185, 129, 0.4)' }
        },
        textStyle: { color: '#94a3b8', fontSize: 9 }
      },
      {
        type: 'inside'
      }
    ],
    xAxis: {
      type: 'time',
      axisLine: { lineStyle: { color: 'rgba(100, 184, 86, 0.25)' } },
      axisTick: { show: true, lineStyle: { color: 'rgba(100, 184, 86, 0.25)' } },
      splitLine: { show: false },
      axisLabel: {
        color: '#94a3b8',
        fontSize: 10,
        formatter: function(val) {
          var d = new Date(val);
          var hh = d.getHours();
          var mm = d.getMinutes();
          if (hh === 0 && mm === 0) {
            return '{dayBadge|' + monthsShort[d.getMonth()] + ' ' + d.getDate() + '}';
          }
          return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
        },
        rich: {
          dayBadge: {
            color: '#ffffff',
            fontWeight: 'bold',
            fontSize: 10,
            backgroundColor: 'rgba(30, 41, 59, 0.9)',
            borderColor: 'rgba(56, 189, 248, 0.5)',
            borderWidth: 1,
            padding: [2, 6],
            borderRadius: 3
          }
        }
      }
    },
    yAxis: {
      type: 'value',
      scale: true,
      axisLine: { show: false },
      axisLabel: { color: '#94a3b8', fontSize: 10, formatter: '{value} kW' },
      splitLine: { lineStyle: { color: 'rgba(255, 255, 255, 0.05)' } }
    },
    series: [
      {
        name: 'PCS-01 (12136)',
        type: 'line',
        data: clean1,
        smooth: 0.35,
        showSymbol: false,
        lineStyle: { color: '#38BDF8', width: 2.0 },
        itemStyle: { color: '#38BDF8' }
      },
      {
        name: 'PCS-02 (12135)',
        type: 'line',
        data: clean2,
        smooth: 0.35,
        showSymbol: false,
        lineStyle: { color: '#10B981', width: 2.0 },
        itemStyle: { color: '#10B981' }
      },
      {
        name: 'PCS-03 (12134)',
        type: 'line',
        data: clean3,
        smooth: 0.35,
        showSymbol: false,
        lineStyle: { color: '#F59E0B', width: 2.0 },
        itemStyle: { color: '#F59E0B' }
      }
    ]
  };

  self.myChart.setOption(option, true);
};

self.onDestroy = function() {
  if (self.myChart) {
    self.myChart.dispose();
    self.myChart = null;
  }
};
